package doc

// Builtins describes what has no declaration in a file: the built-in functions and
// types, the generic constraints and what the compiler rewrites
// (io.print, thread.spawn, the methods of channels and mutexes). Each entry has the
// usage form and the description, in markdown. It's used by mlc doc and by the LSP.
var Builtins = map[string][2]string{
	"alloc":            {"alloc(T) *T · alloc(value) *T · alloc([]T, n) []T", "Allocates on the heap. Returns an owner, which must be freed with `free` (the compiler checks)."},
	"free":             {"free(p)", "Frees an owning pointer or slice. After that the variable can't be used anymore."},
	"realloc":          {"realloc(s []T, n int) []T", "Changes the size of an owning slice: consumes `s` and returns another; the new positions come zeroed."},
	"len":              {"len(s) int", "Length of a slice, array or string (in bytes)."},
	"take":             {"take(&s[i]) ?*T", "Takes the owner out of position `i` of a slice of owners, leaving `nil` in its place."},
	"replace":          {"replace(&s[i], v) ?*T", "Puts `v` at position `i` and returns the owner that was there."},
	"drain":            {"for x in drain(s)", "Walks a slice of owners taking out each element; each `x` must be freed or moved."},
	"print":            {"io.print(a, b, ...)", "Writes the values separated by spaces and ends the line. Each value must implement `io.Display` and is written by its `write` method, over an `io.Writer` with a buffer on the stack (no allocation). The compiler only rewrites the call."},
	"eprint":           {"io.eprint(a, b, ...)", "Like `io.print`, but on standard error."},
	"printf":           {"io.printf(\"x = {}\\n\", x)", "Writes the format replacing each `{}` with a value (which must implement `io.Display`); `{{` and `}}` write braces. The format is a string literal, checked at compile time: the number of `{}` must match the number of values. Specs: `{:x}` `{:X}` `{:b}` `{:o}` `{:#x}` (integers), `{:.2}` (reals), `{:8}` `{:<8}` `{:>8}` `{:^8}` `{:*^8}` (width in characters), `{:08}` (zeros), `{:s}` (the bytes of a `[]byte` as text)."},
	"Thread":           {"thread.Thread[R]", "Handle of a thread created by `thread.spawn`, whose function returns `R` (`thread.Thread` when it returns nothing). It only exists behind a pointer and doesn't accept `free`: it must go to `thread.join`."},
	"Sender":           {"chan.Sender[T]", "Channel end that sends (`send`, `clone`, `close`). It only exists behind a pointer; it needs a `close()` (the compiler checks)."},
	"Receiver":         {"chan.Receiver[T]", "Channel end that receives (`recv`, `sender`, `clone`, `close`). It only exists behind a pointer; it needs a `close()` (the compiler checks)."},
	"chan.new":         {"chan.new[T](cap int) *chan.Receiver[T]", "Allocates a channel with `cap` slots (at least 1) and returns the receiving end. Create the sending ends with `rx.sender()`. The channel is freed on the last `close`."},
	"chan.send":        {"tx.send(v T) bool", "Moves `v` into the channel; waits if it's full. With no `Receiver` open, frees `v` and returns `false`."},
	"chan.try_send":    {"tx.try_send(v T) chan.Try[T]", "Moves `v` into the channel without ever waiting: `Sent`, or `Full(v)` and `Closed(v)`, with `v` given back. For a C callback, which must not block the task that called it."},
	"chan.recv":        {"rx.recv() chan.Recv[T]", "Waits for a value: `Got(v)`, with ownership of `v`, or `Closed`, when every `Sender` closed and the channel is empty."},
	"chan.sender":      {"rx.sender() *chan.Sender[T]", "Creates an end that sends to this channel. It needs a `close()`."},
	"chan.clone":       {"x.clone()", "Another end on the same side (several producers or several consumers). It needs a `close()`."},
	"chan.close":       {"x.close()", "Closes the end (consumes it). The channel's last `close` frees the channel and whatever was left in it."},
	"Mutex":            {"mutex.Mutex[T]", "Handle of a mutex that holds a `T`. `lock()` returns the guard; `clone()` gives another handle (for another thread); each handle needs a `close()`."},
	"Guard":            {"mutex.Guard[T]", "A mutex's lock, owned by the thread that locked. `get()` borrows the value; `unlock()` unlocks (required). It doesn't go to another thread, fields or slices."},
	"mutex.new":        {"mutex.new(v T) *mutex.Mutex[T]", "Allocates a mutex with the value `v` inside (`v` is moved). The last `close` (of handles and guards) frees the value."},
	"mutex.lock":       {"m.lock() *mutex.Guard[T]", "Waits for the lock and returns the guard. Locking again on the same thread without unlocking panics."},
	"mutex.clone":      {"m.clone() *mutex.Mutex[T]", "Another handle to the same mutex, to take to another thread. It needs a `close()`."},
	"mutex.close":      {"m.close()", "Closes the handle (consumes it). The last one to leave frees the value."},
	"mutex.get":        {"g.get() &T", "Borrows the value kept in the mutex. While the borrow is used, the guard stays frozen: you can't unlock before."},
	"mutex.unlock":     {"g.unlock()", "Unlocks the mutex (consumes the guard)."},
	"mutex.wait":       {"g.wait()", "Releases the lock, waits for a `notify` and locks again."},
	"mutex.notify":     {"notify()", "Wakes one thread waiting in `wait`."},
	"mutex.notify_all": {"notify_all()", "Wakes every thread waiting in `wait`."},
	"spawn":            {"thread.spawn(f fn(C) R, ctx C, stack int) *thread.Thread[R]", "Creates a thread that runs `f(ctx)`. The context is **moved** to the thread, and `stack` is the stack size in bytes (at least 16 KB, like `thread.STACK_64KB`). The returned handle must go to `thread.join` (the compiler checks)."},
	"join":             {"thread.join(t *thread.Thread[R]) R", "Waits for the thread to finish and returns `f`'s result, whose ownership comes back to the caller. Frees the thread's record."},
	"Logger.debug":     {"lg.debug(\"...\", a, ...)", "Logs a DEBUG line, with `io.printf`'s format. The values are always computed; the line is only formatted and written if the logger's level allows it."},
	"Logger.info":      {"lg.info(\"...\", a, ...)", "Logs an INFO line, with `io.printf`'s format: `2026-10-19T14:03:22.123-03:00 INFO  ...`. The line comes out whole, even with several threads."},
	"Logger.warn":      {"lg.warn(\"...\", a, ...)", "Logs a WARN line, with `io.printf`'s format."},
	"Logger.error":     {"lg.error(\"...\", a, ...)", "Logs an ERROR line, with `io.printf`'s format."},
	"Writer.printf":    {"w.printf(\"x = {}\\n\", x)", "Writes `io.printf`'s format into the Writer `w`, without creating another and without a `flush` (call `w.flush()` at the end). In a loop, it's as fast as `w.put_int`; inside your own `write`, it takes the parameter's `&io.Writer`."},
	"format":           {"str.format(&dst, \"x = {}\", x) int", "Writes the format into `dst`, like `io.printf`, and returns how many bytes it used; panics if it doesn't fit. It doesn't allocate: to know the size beforehand, use `str.format_len`."},
	"format_len":       {"str.format_len(\"x = {}\", x) int", "How many bytes the format takes, without writing anything: `n := str.format_len(...)`, `b := alloc([]byte, n)`, `str.format(&b, ...)`."},
	"eprintf":          {"io.eprintf(\"error: {}\\n\", e)", "Like `io.printf`, but on standard error."},
	"int":              {"int", "64-bit signed integer. Overflow panics."},
	"int8":             {"int8", "8-bit signed integer (-128 to 127)."},
	"int16":            {"int16", "16-bit signed integer."},
	"int32":            {"int32", "32-bit signed integer."},
	"int64":            {"int64", "64-bit signed integer (the same as `int`)."},
	"uint8":            {"uint8", "8-bit unsigned integer (the same as `byte`)."},
	"uint16":           {"uint16", "16-bit unsigned integer."},
	"uint32":           {"uint32", "32-bit unsigned integer."},
	"uint64":           {"uint64", "64-bit unsigned integer."},
	"byte":             {"byte", "A byte, from 0 to 255. Literal: `'a'`."},
	"float32":          {"float32", "Single-precision real (IEEE 754)."},
	"float64":          {"float64", "Double-precision real (IEEE 754)."},
	"bool":             {"bool", "`true` or `false`."},
	"string":           {"string", "Fixed text of the program (literals). It doesn't allocate and doesn't need `free`."},
	"nil":              {"nil", "Null pointer; only fits in `?*T`."},
	"auto":             {"impl auto io.Display for T", "Generates the `write` method of a struct or enum, in the format `{1 2}` / `Circle(2)`. Each field must implement `io.Display`."},
	"Self":             {"Self", "In an interface, the type that implements it."},
	"true":             {"true", "The true value of `bool`."},
	"false":            {"false", "The false value of `bool`."},
	"any":              {"any", "Generic constraint: any type that isn't an owner."},
	"comparable":       {"comparable", "Generic constraint: types that accept `==` and `!=`."},
	"ordered":          {"ordered", "Generic constraint: numbers, which accept `<`, `>` and arithmetic."},
	"number":           {"number", "Generic constraint: numbers (integers and reals), with `+ - * /`."},
	"integer":          {"integer", "Generic constraint: integers, including `%`."},
	"ref":              {"ref", "Generic constraint: accepts any type, including structs with owners, because the parameter only appears borrowed (`&C`). It's the one for a callback's context: `each_with[C ref](ctx &C, f fn(&C, ...))`."},
	"owned":            {"owned", "Generic constraint: accepts types without owners and simple owners (`?*X`, `[]X`). Inside the body, a value of `T` is treated as an owner: assigning moves, and every value needs a destination (move, store or `drop`)."},
	"drop":             {"drop(x)", "In generic code, consumes `x`: frees it if it's an owner (`free`) and does nothing if it isn't (T = int in an instance)."},
}
